mapper.select:
select count(1) from CHB_TRANSFORM_RULE
where TRANS_TYPE=#{transType,jdbcType=CHAR}
and ORG_FIELD=#{orgField,jdbcType=VARCHAR}
and STATUS !='D'

select SEQNO seqno, TRANS_TYPE transType, ORG_FIELD orgField, PINGYING pinyin, FIELD_UNICODE fieldUnicode, TARGET_FIELD targetField, STATUS dataStatus, IS_MODIFY isModify, REMARK remark, UPDATE_USER updateUser, CREATE_USER createUser, CREATE_DEPT createDept from CHB_TRANSFORM_RULE
#{item,jdbcType=VARCHAR}
and TRANS_TYPE = #{transType,jdbcType=VARCHAR}
and ORG_FIELD = #{orgField,jdbcType=VARCHAR}

select OBJ_TABLE_FILED
from CHB_TRANSFORM_RULE_OBJ
where OBJ_TABLE_ID=#{tableid,jdbcType=VARCHAR}

mapper.update:
update CHB_TRANSFORM_RULE
PINGYING=#{pinyin,jdbcType=VARCHAR} , TARGET_FIELD= #{targetField,jdbcType=VARCHAR} , REMARK=#{remark,jdbcType=VARCHAR}, UPDATE_USER= #{updateUser,jdbcType=VARCHAR}, UPDATE_TIME=NOW()
where SEQNO=#{seqno}
